/**
 * PDF of the nota (DANFSe v2.0), generated by us from the NFS-e XML because
 * the government API that made it was turned off (NT 008/2026, issue #564).
 *
 * Stored at tenants/{cid}/invoices/{id}/danfse.pdf. Made right after the
 * nota is issued, again with the "CANCELADA" watermark when it is canceled,
 * and, for notas imported from the government, the first time someone opens
 * it. Never fails the issue or the cancellation: the next open makes it.
 */

import { db, storage } from '../firestore.service';
import { NfseServiceError } from './errors';
import { parseNfseXml, type CityNames } from './danfse/parse';
import { renderDanfse, type DanfseSituation } from './danfse/render';
import type { NfseDirectInvoiceFields } from '../../models/nfse-direct.types';

export const danfsePdfPath = (companyId: string, invoiceId: string) => `tenants/${companyId}/invoices/${invoiceId}/danfse.pdf`;

export interface DanfseDeps {
  readFile: (path: string) => Promise<string>;
  saveFile: (path: string, contents: Buffer, contentType: string) => Promise<void>;
  /** Name of a city by its IBGE code; null when unknown. */
  cityName: (code: string) => Promise<string | null>;
  now: () => Date;
}

const cityCache = new Map<string, string>();

/** Public IBGE lookup, cached for the life of the instance. */
async function ibgeCityName(code: string): Promise<string | null> {
  if (cityCache.has(code)) return cityCache.get(code)!;
  try {
    const res = await fetch(`https://servicodados.ibge.gov.br/api/v1/localidades/municipios/${code}`, {
      signal: AbortSignal.timeout(5000),
    });
    if (!res.ok) return null;
    const body = (await res.json()) as { nome?: unknown };
    if (typeof body?.nome !== 'string') return null;
    cityCache.set(code, body.nome);
    return body.nome;
  } catch {
    return null;
  }
}

export function defaultDanfseDeps(): DanfseDeps {
  return {
    readFile: async (path) => (await storage.bucket().file(path).download())[0].toString('utf8'),
    saveFile: async (path, contents, contentType) => {
      await storage.bucket().file(path).save(contents, { contentType, resumable: false });
    },
    cityName: ibgeCityName,
    now: () => new Date(),
  };
}

type InvoiceDoc = NfseDirectInvoiceFields & { status?: string };

/** Which watermark the nota needs now. */
export function situationOf(invoice: InvoiceDoc): DanfseSituation | null {
  if (invoice.status === 'authorized' || invoice.status === 'cancellationDenied') return 'normal';
  if (invoice.status === 'canceled') return 'canceled';
  if (invoice.status === 'replaced') return 'replaced';
  return null;
}

/** IBGE codes in the XML (prestador, tomador, destinatário, intermediário...). */
function cityCodesOf(xml: string): string[] {
  return [...new Set([...xml.matchAll(/<(?:\w+:)?cMun>(\d{7})</g)].map((m) => m[1]))];
}

async function cityNamesFor(xml: string, invoice: InvoiceDoc, companyId: string, deps: DanfseDeps): Promise<CityNames> {
  const names: CityNames = {};
  const known = (code?: string | null, name?: string | null) => {
    if (code && name) names[code] = name;
  };
  known(invoice.recipient?.address?.cityCode, invoice.recipient?.address?.cityName);
  if (invoice.emitter?.id) {
    const emitter = await db.collection('companies').doc(companyId).collection('fiscalEmitters').doc(invoice.emitter.id).get();
    const data = emitter.data() as { cityCode?: string; cityName?: string } | undefined;
    known(data?.cityCode, data?.cityName);
  }
  for (const code of cityCodesOf(xml)) {
    if (!names[code]) known(code, await deps.cityName(code));
  }
  return names;
}

/**
 * Makes the PDF when it is missing or has the wrong watermark, and returns
 * its Storage path. [force] makes it again anyway.
 */
export async function ensureDanfse(
  companyId: string,
  invoiceId: string,
  override?: Partial<DanfseDeps>,
  force = false,
): Promise<string> {
  const deps = { ...defaultDanfseDeps(), ...override };
  const ref = db.collection('companies').doc(companyId).collection('invoices').doc(invoiceId);
  const snap = await ref.get();
  if (!snap.exists) throw new NfseServiceError('INVOICE_NOT_FOUND', 'Invoice not found');
  const invoice = snap.data() as InvoiceDoc;
  const situation = situationOf(invoice);
  if (invoice.provider !== 'direct' || !invoice.xmlPath || !situation) {
    throw new NfseServiceError('PDF_NOT_AVAILABLE', 'Only issued direct notas have a PDF here');
  }
  if (!force && invoice.pdfPath && (invoice.pdfSituation ?? 'normal') === situation) return invoice.pdfPath;

  const xml = await deps.readFile(invoice.xmlPath);
  const data = parseNfseXml(xml, await cityNamesFor(xml, invoice, companyId, deps));
  const pdf = await renderDanfse(data, situation);
  const path = danfsePdfPath(companyId, invoiceId);
  await deps.saveFile(path, pdf, 'application/pdf');
  await ref.update({ pdfPath: path, pdfSituation: situation, updatedAt: deps.now().toISOString() });
  return path;
}

/** Best effort after issuing or canceling: a failure only logs; the next open retries. */
export async function refreshDanfse(companyId: string, invoiceId: string, override?: Partial<DanfseDeps>): Promise<void> {
  try {
    await ensureDanfse(companyId, invoiceId, override, true);
  } catch (error) {
    console.error(`[nfse] PDF of invoice ${invoiceId} of company ${companyId} not made`, (error as Error)?.name, (error as Error)?.message?.slice(0, 120));
  }
}
